public class TemperatureTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("new Temperature(25.0).fahrenheit()", 77.0, new Temperature(25.0).fahrenheit());
        check("new Temperature(0.0).fahrenheit()", 32.0, new Temperature(0.0).fahrenheit());
        check("new Temperature(-40.0).fahrenheit()", -40.0, new Temperature(-40.0).fahrenheit());
        Temperature w = new Temperature(20.0).warmer(5.5);
        check("warmer(5.5).celsius()", 25.5, w == null ? null : w.celsius());
        Temperature base = new Temperature(10.0);
        base.warmer(3.0);
        check("warmer does not change the original", 10.0, base.celsius());
        boolean threw = false;
        try {
            new Temperature(-300.0);
        } catch (IllegalArgumentException e) {
            threw = true;
        }
        check("new Temperature(-300.0) throws IllegalArgumentException", true, threw);
        boolean boundaryOk = true;
        try {
            new Temperature(-273.15);
        } catch (IllegalArgumentException e) {
            boundaryOk = false;
        }
        check("new Temperature(-273.15) is allowed", true, boundaryOk);
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

